const counterEl = document.getElementById('counter');
window.MJVideo.BindText('#as-of', '__asOf', (v) => 'Data as of ' + String(v));
window.MJVideo.OnFrame((t, beat) => {
  window.MJChartKit.Counter(counterEl, { Value: Number(window.MJVideo.Data['arr_total']), BindingKey: 'arr_total', Format: 'currency', Unit: 'USD', Precision: 1, StartSeconds: 0, DurationSeconds: 3.5 }, t);
});
